DBMS_OUTPUT.PUT_LINE(q'~  // Windows: history plus the ones open right now~');
DBMS_OUTPUT.PUT_LINE(q'~  const WCFG = rows('wcfg').map((r) => ({~');
DBMS_OUTPUT.PUT_LINE(q'~    con: r[0], name: r[1], enabled: r[2], active: r[3], repeat: r[4], secs: r[5],~');
DBMS_OUTPUT.PUT_LINE(q'~    next: ts(r[6]), last: ts(r[7]), maint: r[8] === 'Y'~');
DBMS_OUTPUT.PUT_LINE(q'~  }));~');
DBMS_OUTPUT.PUT_LINE(q'~  const MAINT = new Set(WCFG.filter((w) => w.maint).map((w) => conKey(w.con, w.name)));~');
