DBMS_OUTPUT.PUT_LINE(q'~  WCFG.forEach((w) => {~');
DBMS_OUTPUT.PUT_LINE(q'~    if (w.active === 'TRUE' && w.last) {~');
DBMS_OUTPUT.PUT_LINE(q'~      WINS.push({ con: w.con, name: w.name, start: w.last, planned: w.secs, secs: null, end: Math.min(w.last + w.secs * 1000, GEN), open: true });~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~  });~');
DBMS_OUTPUT.PUT_LINE(q'~  WINS.forEach((w) => { w.maint = MAINT.has(conKey(w.con, w.name)) || /_WINDOW$/.test(w.name); });~');
