DBMS_OUTPUT.PUT_LINE(q'~    if (!TPREFMAP.has(k)) TPREFMAP.set(k, []);~');
DBMS_OUTPUT.PUT_LINE(q'~    TPREFMAP.get(k).push(p);~');
