DBMS_OUTPUT.PUT_LINE(q'~  const SEV_ICON = { good: '\u2713', info: 'i', warn: '!', serious: '!', crit: '\u2715' };~');
DBMS_OUTPUT.PUT_LINE(q'~  OPS.forEach((o) => {~');
