DBMS_OUTPUT.PUT_LINE(q'~      else if (a.status === 'FAILED') s.failed += a.n;~');
DBMS_OUTPUT.PUT_LINE(q'~      else s.notDone += a.n;~');
DBMS_OUTPUT.PUT_LINE(q'~      const bt = s.byType[a.type] || (s.byType[a.type] = { n: 0, done: 0, failed: 0, other: 0, secs: 0, size: 0, hist: 0 });~');
DBMS_OUTPUT.PUT_LINE(q'~      bt.n += a.n; bt.secs += a.secs; bt.size += a.size; bt.hist += a.hist;~');
DBMS_OUTPUT.PUT_LINE(q'~      if (a.status === 'COMPLETED') bt.done += a.n; else if (a.status === 'FAILED') bt.failed += a.n; else bt.other += a.n;~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    o.stats = s;~');
DBMS_OUTPUT.PUT_LINE(q'~    o.truncated = o.tasks.length < s.n;~');
