DBMS_OUTPUT.PUT_LINE(q'~    const runs = o.job ? SJR.get(conKey(o.con, o.job)) || [] : [];~');
DBMS_OUTPUT.PUT_LINE(q'~    o.sjr = runs.find((j) => j.start <= o.start + 5000 && j.start + (j.secs + 5) * 1000 >= o.start) || null;~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.ajh) {~');
