DBMS_OUTPUT.PUT_LINE(q'~    } else {~');
DBMS_OUTPUT.PUT_LINE(q'~      const w = WINS.find((w) => w.con === o.con && w.start <= o.start && o.start < w.end);~');
DBMS_OUTPUT.PUT_LINE(q'~      o.window = w ? { name: w.name, start: w.start, end: w.end, secs: (w.end - w.start) / 1000, open: w.open } : null;~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~  });~');
DBMS_OUTPUT.PUT_LINE(q'~  // Recurring failures: the same object failing with the same error across runs~');
DBMS_OUTPUT.PUT_LINE(q'~  const FAILS = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~  function addFail(con, target, error, o, when) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const err = (error || 'no error text recorded').replace(/\s+/g, ' ').slice(0, 300);~');
DBMS_OUTPUT.PUT_LINE(q'~    const k = con + '|' + target + '|' + err;~');
DBMS_OUTPUT.PUT_LINE(q'~    let f = FAILS.get(k);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!f) FAILS.set(k, f = { con: con, target: target, error: err, runs: new Set(), first: when, last: when, lastOp: o });~');
DBMS_OUTPUT.PUT_LINE(q'~    f.runs.add(o.key);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (when < f.first) f.first = when;~');
DBMS_OUTPUT.PUT_LINE(q'~    if (when >= f.last) { f.last = when; f.lastOp = o; }~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  TASKS.forEach((t) => { if (t.status === 'FAILED' && t.op) addFail(t.con, showTarget(t.target), t.error || t.op.error, t.op, t.start || t.op.start); });~');
DBMS_OUTPUT.PUT_LINE(q'~  OPS.forEach((o) => {~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.kind === 'gather' && o.status === 'FAILED' && !o.stats.failed) addFail(o.con, showTarget(o.target), o.error, o, o.start);~');
DBMS_OUTPUT.PUT_LINE(q'~  });~');
DBMS_OUTPUT.PUT_LINE(q'~  const FAILLIST = [...FAILS.values()].sort((a, b) => b.runs.size - a.runs.size || b.last - a.last);~');
DBMS_OUTPUT.PUT_LINE(q'~  // Failures Oracle documents as expected; they do not make a run incomplete~');
DBMS_OUTPUT.PUT_LINE(q'~  const BENIGN = [~');
DBMS_OUTPUT.PUT_LINE(q'~    { re: /X\$LOGMNR_CONTENTS.*log ?miner or data guard must be started/i, why: 'X$LOGMNR_CONTENTS can only be analyzed while LogMiner runs; the automatic job tries it every time. Harmless.' }~');
DBMS_OUTPUT.PUT_LINE(q'~  ];~');
DBMS_OUTPUT.PUT_LINE(q'~  const benign = (err) => BENIGN.find((b) => b.re.test(err || '')) || null;~');
DBMS_OUTPUT.PUT_LINE(q'~  FAILLIST.forEach((f) => { f.benign = benign(f.target + ' ' + f.error); });~');
DBMS_OUTPUT.PUT_LINE(q'~  const chronic = new Set(FAILLIST.filter((f) => f.runs.size >= 3).map((f) => f.con + '|' + f.target));~');
DBMS_OUTPUT.PUT_LINE(q'~  function verdict(o) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const s = o.stats;~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.status === 'FAILED') return { sev: 'crit', label: 'Failed', why: o.error || 'The operation failed.' };~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.status === 'TIMED OUT') return { sev: 'crit', label: 'Timed out', why: 'Stopped before finishing (end of the maintenance window or AUTO_TASK_MAX_RUN_TIME).' + (s.notDone ? ' ' + fmtN(s.notDone) + ' objects not processed.' : '') };~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.abandoned) return { sev: 'crit', label: 'Never finished', why: 'Still IN PROGRESS a day later: the session ended (killed, instance restart) before the operation could record its end.' };~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.status === 'IN PROGRESS') return { sev: 'info', label: 'Running', why: 'In progress when the report was generated.' };~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.ajh && /STOPPED|FAILED|BROKEN/.test(o.ajh.status)) return { sev: 'crit', label: 'Job ' + o.ajh.status.toLowerCase(), why: o.ajh.info || 'The scheduler reports the job as ' + o.ajh.status + '.' };~');
END;
/
BEGIN
DBMS_OUTPUT.PUT_LINE(q'~    if (s.notDone) return { sev: 'crit', label: fmtN(s.notDone) + ' not processed', why: fmtN(s.notDone) + ' objects were queued but never completed (status pending, skipped or timed out).' };~');
DBMS_OUTPUT.PUT_LINE(q'~    const fails = o.tasks.filter((t) => t.status === 'FAILED');~');
DBMS_OUTPUT.PUT_LINE(q'~    const expected = fails.filter((t) => benign(t.name + ' ' + t.error)).length;~');
DBMS_OUTPUT.PUT_LINE(q'~    if (s.failed && expected === s.failed) {~');
DBMS_OUTPUT.PUT_LINE(q'~      return { sev: 'good', label: 'Complete', why: 'Every object it picked was gathered, except ' + plural(expected, 'expected failure') + ' (' + fails.map((t) => t.name).join(', ') + ').', expected: expected };~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    if (s.failed) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const allChronic = fails.length === s.failed && fails.every((t) => chronic.has(t.con + '|' + showTarget(t.target)));~');
DBMS_OUTPUT.PUT_LINE(q'~      return { sev: 'warn', label: fmtN(s.failed) + ' failed', why: fmtN(s.failed) + ' of ' + fmtN(s.n) + ' objects failed' + (allChronic ? ' (the same objects fail in every run).' : '.') };~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.status && o.status !== 'COMPLETED') return { sev: 'warn', label: titleCase(o.status), why: 'Status ' + o.status + '.' };~');
DBMS_OUTPUT.PUT_LINE(q'~    return { sev: 'good', label: 'Complete', why: o.kind === 'other' ? 'Completed.' : 'Every object it picked was gathered.' };~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  OPS.forEach((o) => { o.v = verdict(o); });~');
DBMS_OUTPUT.PUT_LINE(q'~  const AUTO = OPS.filter((o) => o.kind === 'auto');~');
DBMS_OUTPUT.PUT_LINE(q'~  const GATHERS = OPS.filter((o) => o.kind === 'gather');~');
DBMS_OUTPUT.PUT_LINE(q'~  const lastAuto = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~  AUTO.forEach((o) => { const l = lastAuto.get(o.con); if (!l || o.start > l.start) lastAuto.set(o.con, o); });~');
DBMS_OUTPUT.PUT_LINE(q'~  // ------------------------------------------- derived: still needing stats~');
DBMS_OUTPUT.PUT_LINE(q'~  const lastAttempt = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~  TASKS.forEach((t) => {~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!t.start) return;~');
DBMS_OUTPUT.PUT_LINE(q'~    const k = conKey(t.con, t.name);~');
DBMS_OUTPUT.PUT_LINE(q'~    const l = lastAttempt.get(k);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!l || t.start > l.start) lastAttempt.set(k, t);~');
DBMS_OUTPUT.PUT_LINE(q'~  });~');
DBMS_OUTPUT.PUT_LINE(q'~  OPS.forEach((o) => {~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.kind !== 'gather' || !/table_stats$/.test(o.op)) return;~');
DBMS_OUTPUT.PUT_LINE(q'~    const k = conKey(o.con, showTarget(o.target) + (o.params.partname ? '.' + o.params.partname : ''));~');
DBMS_OUTPUT.PUT_LINE(q'~    const l = lastAttempt.get(k);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!l || o.start > l.start) lastAttempt.set(k, { start: o.start, status: o.status, error: o.error, op: o });~');
DBMS_OUTPUT.PUT_LINE(q'~  });~');
DBMS_OUTPUT.PUT_LINE(q'~  const CATS = {~');
DBMS_OUTPUT.PUT_LINE(q'~    failed: { sev: 'crit', title: 'Last gather failed', text: 'The most recent attempt to gather this object in the period failed. It stays stale until the error is fixed.' },~');
DBMS_OUTPUT.PUT_LINE(q'~    missed: { sev: 'crit', title: 'Missed by the last automatic run', text: 'Its changes were recorded before the last automatic run started, yet that run did not gather it (run stopped early, object outside AUTOSTATS_TARGET, or a table preference).' },~');
DBMS_OUTPUT.PUT_LINE(q'~    locked: { sev: 'warn', title: 'Stale or missing, but locked', text: 'Statistics are locked: the automatic job and every gather without FORCE skip it. Intentional for some tables; check it is.' },~');
DBMS_OUTPUT.PUT_LINE(q'~    missing: { sev: 'warn', title: 'No statistics at all', text: 'Never gathered. The optimizer falls back to dynamic sampling. The automatic job gathers these first, so check why it has not.' },~');
DBMS_OUTPUT.PUT_LINE(q'~    fresh: { sev: 'info', title: 'Stale since the last automatic run', text: 'Changed after the last automatic run started. The next run is expected to pick it up; nothing missed yet.' },~');
DBMS_OUTPUT.PUT_LINE(q'~    stale: { sev: 'info', title: 'Stale, time of change unknown', text: 'Marked stale but no DML monitoring row tells when it changed (e.g. no automatic run in the period to compare with).' },~');
DBMS_OUTPUT.PUT_LINE(q'~    missingSub: { sev: 'info', title: 'Subpartitions without statistics', text: 'Usually by design: GRANULARITY AUTO does not gather subpartition statistics for every subpartitioning type.' },~');
DBMS_OUTPUT.PUT_LINE(q'~    fixed: { sev: 'info', title: 'Fixed objects (X$) without statistics', text: 'Gathered only by GATHER_FIXED_OBJECTS_STATS or GATHER_DICTIONARY_STATS; some X$ tables can never be analyzed.' }~');
DBMS_OUTPUT.PUT_LINE(q'~  };~');
DBMS_OUTPUT.PUT_LINE(q'~  const CAT_ORDER = ['failed', 'missed', 'locked', 'missing', 'fresh', 'stale', 'missingSub', 'fixed'];~');
DBMS_OUTPUT.PUT_LINE(q'~  const BL = rows('bl').map((r) => {~');
DBMS_OUTPUT.PUT_LINE(q'~    const b = {~');
DBMS_OUTPUT.PUT_LINE(q'~      con: r[0], owner: r[1], table: r[2], part: r[3], sub: r[4], type: r[5] || '',~');
DBMS_OUTPUT.PUT_LINE(q'~      rows: r[6], blocks: r[7], analyzed: ts(r[8]), stale: r[9] === 'YES', locked: r[10],~');
DBMS_OUTPUT.PUT_LINE(q'~      ins: r[11], upd: r[12], del: r[13], trunc: r[14] === 'YES', dmlTs: ts(r[15]), om: r[16] === 'Y'~');
DBMS_OUTPUT.PUT_LINE(q'~    };~');
DBMS_OUTPUT.PUT_LINE(q'~    b.name = [b.owner, b.table, b.part, b.sub].filter(Boolean).join('.');~');
DBMS_OUTPUT.PUT_LINE(q'~    b.missing = !b.analyzed;~');
DBMS_OUTPUT.PUT_LINE(q'~    const la = lastAuto.get(b.con);~');
DBMS_OUTPUT.PUT_LINE(q'~    const att = lastAttempt.get(conKey(b.con, b.name)) ||~');
DBMS_OUTPUT.PUT_LINE(q'~      (b.sub ? lastAttempt.get(conKey(b.con, [b.owner, b.table, b.sub].join('.'))) : null);~');
DBMS_OUTPUT.PUT_LINE(q'~    b.attempt = att || null;~');
DBMS_OUTPUT.PUT_LINE(q'~    b.prefs = TPREFMAP.get(conKey(b.con, b.owner + '.' + b.table)) || [];~');
DBMS_OUTPUT.PUT_LINE(q'~    if (att && att.status === 'FAILED') b.cat = 'failed';~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (b.locked) b.cat = 'locked';~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (b.type === 'FIXED TABLE') b.cat = 'fixed';~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (b.missing && b.type === 'SUBPARTITION') b.cat = 'missingSub';~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (b.missing) b.cat = 'missing';~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (b.dmlTs && la && b.dmlTs < la.start) b.cat = 'missed';~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (b.dmlTs && la) b.cat = 'fresh';~');
DBMS_OUTPUT.PUT_LINE(q'~    else b.cat = 'stale';~');
DBMS_OUTPUT.PUT_LINE(q'~    b.dml = (b.ins || 0) + (b.upd || 0) + (b.del || 0);~');
DBMS_OUTPUT.PUT_LINE(q'~    b.pct = b.rows ? (100 * b.dml) / b.rows : null;~');
DBMS_OUTPUT.PUT_LINE(q'~    return b;~');
DBMS_OUTPUT.PUT_LINE(q'~  });~');
DBMS_OUTPUT.PUT_LINE(q'~  const BLAGG = rows('blagg').map((r) => ({ con: r[0], om: r[1] === 'Y', type: r[2], stale: r[3] === 'Y', missing: r[4] === 'Y', locked: r[5] === 'Y', n: r[6] }));~');
DBMS_OUTPUT.PUT_LINE(q'~  const blTruncated = BL.length >= (META.maxBacklog || 5000);~');
DBMS_OUTPUT.PUT_LINE(q'~  function sevBadge(sev, label, tip) {~');
DBMS_OUTPUT.PUT_LINE(q'~    return '<span class="sev ' + sev + '"' + (tip ? ' data-tip="' + esc(tip) + '"' : '') + '><i>' + SEV_ICON[sev] + '</i>' + esc(label) + '</span>';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  const kindLabel = { auto: 'Automatic job', gather: 'Manual / custom gather', other: 'Other DBMS_STATS call' };~');
DBMS_OUTPUT.PUT_LINE(q'~  function opLabel(o) {~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.kind === 'auto') return o.highFreq ? 'Automatic job (high-frequency)' : 'Automatic job';~');
DBMS_OUTPUT.PUT_LINE(q'~    return o.op;~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function opTarget(o) {~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.kind === 'auto') return 'database (AUTO)';~');
DBMS_OUTPUT.PUT_LINE(q'~    const t = showTarget(o.target);~');
DBMS_OUTPUT.PUT_LINE(q'~    return t + (o.params.partname ? '.' + o.params.partname : '');~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function opTip(o) {~');
DBMS_OUTPUT.PUT_LINE(q'~    return '<b>' + esc(opLabel(o)) + '</b> ' + (o.kind === 'auto' ? '' : esc(opTarget(o))) +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<br>' + esc(conName(o.con)) + ' &middot; ' + esc(fmtT(o.start, true)) + ' &middot; ' + esc(fmtDur(o.secs)) +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<br>' + (o.stats.n ? plural(o.stats.n, 'object') + ' &middot; ' : '') + esc(o.v.label) +~');
DBMS_OUTPUT.PUT_LINE(q'~      (o.v.sev !== 'good' ? '<br><span class="muted">' + esc(o.v.why) + '</span>' : '');~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // ---------------------------------------------------------------- tables~');
DBMS_OUTPUT.PUT_LINE(q'~  // spec: { cols: [{ key, label, num, cls, html(r), val(r), tip }], rows, sort: [key, dir], limit, href(r), empty }~');
DBMS_OUTPUT.PUT_LINE(q'~  function renderTable(host, spec) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const st = host._t || (host._t = { sort: spec.sort || null, limit: spec.limit || 300 });~');
DBMS_OUTPUT.PUT_LINE(q'~    const cols = spec.cols;~');
DBMS_OUTPUT.PUT_LINE(q'~    let data = spec.rows.slice();~');
DBMS_OUTPUT.PUT_LINE(q'~    if (st.sort) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const c = cols.find((c) => c.key === st.sort[0]);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (c) {~');
DBMS_OUTPUT.PUT_LINE(q'~        const val = c.val || ((r) => r[c.key]);~');
DBMS_OUTPUT.PUT_LINE(q'~        const dir = st.sort[1];~');
DBMS_OUTPUT.PUT_LINE(q'~        data.sort((a, b) => {~');
DBMS_OUTPUT.PUT_LINE(q'~          const x = val(a), y = val(b);~');
DBMS_OUTPUT.PUT_LINE(q'~          if (x == null && y == null) return 0;~');
DBMS_OUTPUT.PUT_LINE(q'~          if (x == null) return 1;~');
DBMS_OUTPUT.PUT_LINE(q'~          if (y == null) return -1;~');
DBMS_OUTPUT.PUT_LINE(q'~          return (x < y ? -1 : x > y ? 1 : 0) * dir;~');
DBMS_OUTPUT.PUT_LINE(q'~        });~');
DBMS_OUTPUT.PUT_LINE(q'~      }~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    const shown = data.slice(0, st.limit);~');
DBMS_OUTPUT.PUT_LINE(q'~    let h = '<div class="tablewrap"><table><thead><tr>';~');
DBMS_OUTPUT.PUT_LINE(q'~    cols.forEach((c) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const sorted = st.sort && st.sort[0] === c.key;~');
DBMS_OUTPUT.PUT_LINE(q'~      h += '<th data-sort="' + c.key + '" class="' + (c.num ? 'num ' : '') + (sorted ? 'sorted' + (st.sort[1] > 0 ? ' asc' : '') : '') + '"' +~');
DBMS_OUTPUT.PUT_LINE(q'~        (c.tip ? ' data-tip="' + esc(c.tip) + '"' : '') + '>' + esc(c.label) + '</th>';~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    h += '</tr></thead><tbody>';~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!shown.length) h += '<tr><td colspan="' + cols.length + '" class="note">' + esc(spec.empty || 'Nothing to show.') + '</td></tr>';~');
DBMS_OUTPUT.PUT_LINE(q'~    shown.forEach((r) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const href = spec.href ? spec.href(r) : null;~');
DBMS_OUTPUT.PUT_LINE(q'~      h += '<tr' + (href ? ' class="click" data-href="' + esc(href) + '"' : '') + '>';~');
DBMS_OUTPUT.PUT_LINE(q'~      cols.forEach((c) => {~');
DBMS_OUTPUT.PUT_LINE(q'~        const v = c.html ? c.html(r) : esc(r[c.key]);~');
DBMS_OUTPUT.PUT_LINE(q'~        h += '<td class="' + (c.num ? 'num ' : '') + (c.cls || '') + '">' + (v == null ? '' : v) + '</td>';~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~      h += '</tr>';~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    h += '</tbody></table></div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    if (data.length > shown.length) {~');
DBMS_OUTPUT.PUT_LINE(q'~      h += '<div class="more-rows note">Showing ' + fmtN(shown.length) + ' of ' + fmtN(data.length) + ' rows. <button type="button">Show 500 more</button></div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    } else if (data.length > 20) {~');
DBMS_OUTPUT.PUT_LINE(q'~      h += '<div class="more-rows note">' + fmtN(data.length) + ' rows.</div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    host.innerHTML = h;~');
DBMS_OUTPUT.PUT_LINE(q'~    host.querySelectorAll('th[data-sort]').forEach((th) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      th.onclick = () => {~');
DBMS_OUTPUT.PUT_LINE(q'~        const k = th.getAttribute('data-sort');~');
DBMS_OUTPUT.PUT_LINE(q'~        const c = cols.find((c) => c.key === k);~');
DBMS_OUTPUT.PUT_LINE(q'~        st.sort = st.sort && st.sort[0] === k ? [k, -st.sort[1]] : [k, c && (c.num || c.desc) ? -1 : 1];~');
DBMS_OUTPUT.PUT_LINE(q'~        renderTable(host, spec);~');
DBMS_OUTPUT.PUT_LINE(q'~      };~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    const more = host.querySelector('.more-rows button');~');
DBMS_OUTPUT.PUT_LINE(q'~    if (more) more.onclick = () => { st.limit += 500; renderTable(host, spec); };~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // ---------------------------------------------------------------- charts~');
DBMS_OUTPUT.PUT_LINE(q'~  function niceMax(v) {~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!(v > 0)) return 1;~');
DBMS_OUTPUT.PUT_LINE(q'~    const p = Math.pow(10, Math.floor(Math.log10(v)));~');
DBMS_OUTPUT.PUT_LINE(q'~    const f = v / p;~');
DBMS_OUTPUT.PUT_LINE(q'~    return (f <= 1 ? 1 : f <= 2 ? 2 : f <= 5 ? 5 : 10) * p;~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function timeTicks(a, b, width, minPx) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const span = b - a;~');
DBMS_OUTPUT.PUT_LINE(q'~    const steps = [5 * 60e3, 15 * 60e3, 30 * 60e3, 3600e3, 2 * 3600e3, 3 * 3600e3, 6 * 3600e3, 12 * 3600e3, DAY, 2 * DAY, 7 * DAY, 14 * DAY, 28 * DAY];~');
DBMS_OUTPUT.PUT_LINE(q'~    const step = steps.find((s) => (s / span) * width >= minPx) || 28 * DAY;~');
DBMS_OUTPUT.PUT_LINE(q'~    const out = [];~');
DBMS_OUTPUT.PUT_LINE(q'~    let t;~');
DBMS_OUTPUT.PUT_LINE(q'~    if (step >= DAY) {~');
DBMS_OUTPUT.PUT_LINE(q'~      t = dayStart(a);~');
DBMS_OUTPUT.PUT_LINE(q'~      while (t < a) t += DAY;~');
DBMS_OUTPUT.PUT_LINE(q'~      for (; t <= b; t += step) out.push(t);~');
DBMS_OUTPUT.PUT_LINE(q'~    } else {~');
DBMS_OUTPUT.PUT_LINE(q'~      const off = tzOff(a) * 60000;~');
DBMS_OUTPUT.PUT_LINE(q'~      t = Math.ceil((a + off) / step) * step - off;~');
DBMS_OUTPUT.PUT_LINE(q'~      for (; t <= b; t += step) out.push(t);~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    return { ticks: out, step: step };~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function tickLabel(t, step) {~');
DBMS_OUTPUT.PUT_LINE(q'~    if (step >= DAY) return fmtT(t).slice(5, 10);~');
DBMS_OUTPUT.PUT_LINE(q'~    const c = fmtClock(t);~');
DBMS_OUTPUT.PUT_LINE(q'~    return c === '00:00' ? fmtT(t).slice(5, 10) : c;~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // Overview timeline: one lane pair per container (automatic job, other gathers) over the whole period~');
DBMS_OUTPUT.PUT_LINE(q'~  function timelineSVG(width, from, to, cons) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const L = 150, R = 12, laneH = 18, gap = 12, top = 4;~');
DBMS_OUTPUT.PUT_LINE(q'~    const W = Math.max(200, width - L - R);~');
DBMS_OUTPUT.PUT_LINE(q'~    const x = (t) => L + ((t - from) / (to - from)) * W;~');
DBMS_OUTPUT.PUT_LINE(q'~    const H = top + cons.length * (2 * laneH + gap) + 22;~');
DBMS_OUTPUT.PUT_LINE(q'~    const tt = timeTicks(from, to, W, 70);~');
DBMS_OUTPUT.PUT_LINE(q'~    let s = '<svg width="' + width + '" height="' + H + '" role="img" aria-label="Timeline of statistics operations">';~');
DBMS_OUTPUT.PUT_LINE(q'~    tt.ticks.forEach((t) => { s += '<line class="grid" x1="' + x(t) + '" x2="' + x(t) + '" y1="' + top + '" y2="' + (H - 20) + '"/>'; });~');
DBMS_OUTPUT.PUT_LINE(q'~    cons.forEach((con, i) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const y0 = top + i * (2 * laneH + gap);~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<text class="lane-label" x="0" y="' + (y0 + 13) + '">' + esc(conName(con)) + '</text>';~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<text x="0" y="' + (y0 + 13) + '" dx="' + (L - 8) + '" text-anchor="end">auto job</text>';~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<text x="0" y="' + (y0 + laneH + 13) + '" dx="' + (L - 8) + '" text-anchor="end">other gathers</text>';~');
DBMS_OUTPUT.PUT_LINE(q'~      WINS.filter((w) => w.con === con && w.maint && w.end > from && w.start < to).forEach((w) => {~');
DBMS_OUTPUT.PUT_LINE(q'~        const a = Math.max(x(w.start), L), b = Math.min(x(w.end), L + W);~');
DBMS_OUTPUT.PUT_LINE(q'~        s += '<rect class="win" x="' + a + '" y="' + y0 + '" width="' + Math.max(1, b - a) + '" height="' + laneH + '" data-tip="' +~');
DBMS_OUTPUT.PUT_LINE(q'~          esc('<b>' + esc(w.name) + '</b>' + (w.open ? ' (open now)' : '') + '<br>' + esc(fmtT(w.start)) + ' \u2192 ' + esc(fmtT(w.end)) + ' &middot; ' + esc(fmtDur((w.end - w.start) / 1000))) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<line class="axis" x1="' + L + '" x2="' + (L + W) + '" y1="' + (y0 + 2 * laneH + 0.5) + '" y2="' + (y0 + 2 * laneH + 0.5) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~      const ops = OPS.filter((o) => o.con === con && o.kind !== 'other' && o.endEff >= from && o.start <= to)~');
DBMS_OUTPUT.PUT_LINE(q'~        .sort((a, b) => SEV_RANK[a.v.sev] - SEV_RANK[b.v.sev]);~');
DBMS_OUTPUT.PUT_LINE(q'~      ops.forEach((o) => {~');
DBMS_OUTPUT.PUT_LINE(q'~        const y = y0 + (o.kind === 'auto' ? 0 : laneH) + 3;~');
DBMS_OUTPUT.PUT_LINE(q'~        const a = x(Math.max(o.start, from));~');
DBMS_OUTPUT.PUT_LINE(q'~        const w = Math.max(4, x(Math.min(o.endEff, to)) - a);~');
DBMS_OUTPUT.PUT_LINE(q'~        s += '<rect class="mark f-' + o.v.sev + '" x="' + (a - (w === 4 ? 2 : 0)) + '" y="' + y + '" width="' + w + '" height="' + (laneH - 6) + '" rx="2" data-href="#run/' + o.key + '" data-tip="' + esc(opTip(o)) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    tt.ticks.forEach((t) => { s += '<text x="' + x(t) + '" y="' + (H - 6) + '" text-anchor="middle">' + esc(tickLabel(t, tt.step)) + '</text>'; });~');
DBMS_OUTPUT.PUT_LINE(q'~    return s + '</svg>';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // Columns over the same time axis: one value per automatic run, colored by container~');
DBMS_OUTPUT.PUT_LINE(q'~  function runColumnsSVG(width, from, to, runs, val, fmt, label) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const L = 150, R = 12, H = 120, top = 8, bottom = 22;~');
DBMS_OUTPUT.PUT_LINE(q'~    const W = Math.max(200, width - L - R);~');
DBMS_OUTPUT.PUT_LINE(q'~    const x = (t) => L + ((t - from) / (to - from)) * W;~');
DBMS_OUTPUT.PUT_LINE(q'~    const max = niceMax(Math.max(0, ...runs.map(val)));~');
DBMS_OUTPUT.PUT_LINE(q'~    const y = (v) => top + (H - top - bottom) * (1 - v / max);~');
DBMS_OUTPUT.PUT_LINE(q'~    const cons = [...new Set(runs.map((o) => o.con))].sort((a, b) => a - b);~');
DBMS_OUTPUT.PUT_LINE(q'~    const tt = timeTicks(from, to, W, 70);~');
DBMS_OUTPUT.PUT_LINE(q'~    let s = '<svg width="' + width + '" height="' + H + '" role="img" aria-label="' + esc(label) + '">';~');
DBMS_OUTPUT.PUT_LINE(q'~    [0, max / 2, max].forEach((v) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<line class="grid" x1="' + L + '" x2="' + (L + W) + '" y1="' + y(v) + '" y2="' + y(v) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<text x="' + (L - 8) + '" y="' + (y(v) + 4) + '" text-anchor="end">' + esc(v ? fmt(v) : '0') + '</text>';~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    runs.forEach((o) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const v = val(o);~');
DBMS_OUTPUT.PUT_LINE(q'~      const cx = x(o.start), yy = y(v), h = Math.max(1, y(0) - yy);~');
DBMS_OUTPUT.PUT_LINE(q'~      const ci = cons.indexOf(o.con) % 3 + 1;~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<rect class="hit" x="' + (cx - 4) + '" y="' + top + '" width="8" height="' + (H - top - bottom) + '" data-href="#run/' + o.key + '" data-tip="' + esc(opTip(o)) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<path class="mark f-s' + ci + '" pointer-events="none" d="M' + (cx - 2) + ',' + y(0) + 'V' + (yy + 2) + 'q0,-2 2,-2q2,0 2,2V' + y(0) + 'Z" data-h="' + h + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    s += '<line class="axis" x1="' + L + '" x2="' + (L + W) + '" y1="' + y(0) + '" y2="' + y(0) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~    tt.ticks.forEach((t) => { s += '<text x="' + x(t) + '" y="' + (H - 6) + '" text-anchor="middle">' + esc(tickLabel(t, tt.step)) + '</text>'; });~');
DBMS_OUTPUT.PUT_LINE(q'~    return s + '</svg>';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // One run's objects over time.  Up to 40 objects: one labelled row each.~');
DBMS_OUTPUT.PUT_LINE(q'~  // More: packed lanes, each object in the first lane free at its start, so~');
DBMS_OUTPUT.PUT_LINE(q'~  // serial work shares a lane and concurrent work stacks.~');
DBMS_OUTPUT.PUT_LINE(q'~  const typeClass = (t) => (t.status === 'FAILED' ? 'f-crit' : t.status !== 'COMPLETED' ? 'f-warn'~');
DBMS_OUTPUT.PUT_LINE(q'~    : /INDEX/.test(t.type) ? 'f-s3' : /PARTITION/.test(t.type) ? 'f-s2' : 'f-s1');~');
DBMS_OUTPUT.PUT_LINE(q'~  function ganttSVG(width, o, tasks) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const timed = tasks.filter((t) => t.start).sort((a, b) => a.start - b.start || (b.secs || 0) - (a.secs || 0));~');
DBMS_OUTPUT.PUT_LINE(q'~    const rowsMode = timed.length <= 40;~');
DBMS_OUTPUT.PUT_LINE(q'~    const MAXL = 24;~');
DBMS_OUTPUT.PUT_LINE(q'~    const lanes = [];~');
DBMS_OUTPUT.PUT_LINE(q'~    const lane = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!rowsMode) {~');
DBMS_OUTPUT.PUT_LINE(q'~      timed.forEach((t) => {~');
DBMS_OUTPUT.PUT_LINE(q'~        const end = t.end || t.start;~');
DBMS_OUTPUT.PUT_LINE(q'~        let i = lanes.findIndex((e) => e <= t.start);~');
DBMS_OUTPUT.PUT_LINE(q'~        if (i < 0) {~');
DBMS_OUTPUT.PUT_LINE(q'~          if (lanes.length < MAXL) i = lanes.push(end) - 1;~');
DBMS_OUTPUT.PUT_LINE(q'~          else i = lanes.indexOf(Math.min(...lanes));~');
DBMS_OUTPUT.PUT_LINE(q'~        }~');
END;
/
BEGIN
DBMS_OUTPUT.PUT_LINE(q'~        lanes[i] = Math.max(lanes[i] || 0, end);~');
DBMS_OUTPUT.PUT_LINE(q'~        lane.set(t, i);~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    const n = rowsMode ? timed.length : lanes.length;~');
DBMS_OUTPUT.PUT_LINE(q'~    const rowH = rowsMode ? 18 : 16;~');
DBMS_OUTPUT.PUT_LINE(q'~    const L = rowsMode ? 280 : 60, R = 12, top = 4, bottom = 22;~');
DBMS_OUTPUT.PUT_LINE(q'~    const W = Math.max(200, width - L - R);~');
DBMS_OUTPUT.PUT_LINE(q'~    const from = Math.min(o.start, ...timed.map((t) => t.start));~');
DBMS_OUTPUT.PUT_LINE(q'~    const to = Math.max(o.endEff, ...timed.map((t) => t.end || t.start), from + 1000);~');
DBMS_OUTPUT.PUT_LINE(q'~    const x = (t) => L + ((t - from) / (to - from)) * W;~');
DBMS_OUTPUT.PUT_LINE(q'~    const H = top + n * rowH + bottom;~');
DBMS_OUTPUT.PUT_LINE(q'~    const tt = timeTicks(from, to, W, 80);~');
DBMS_OUTPUT.PUT_LINE(q'~    let s = '<svg width="' + width + '" height="' + H + '" role="img" aria-label="Objects of this run over time">';~');
DBMS_OUTPUT.PUT_LINE(q'~    tt.ticks.forEach((t) => { s += '<line class="grid" x1="' + x(t) + '" x2="' + x(t) + '" y1="' + top + '" y2="' + (H - bottom) + '"/>'; });~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!rowsMode) {~');
DBMS_OUTPUT.PUT_LINE(q'~      for (let i = 0; i < n; i++) s += '<text x="' + (L - 8) + '" y="' + (top + i * rowH + 12) + '" text-anchor="end">' + (i + 1) + '</text>';~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.window && o.window.end > from && o.window.end <= to) {~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<line x1="' + x(o.window.end) + '" x2="' + x(o.window.end) + '" y1="' + top + '" y2="' + (H - bottom) + '" stroke="var(--crit)" stroke-width="1.5"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    timed.forEach((t, i) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const y = top + (rowsMode ? i : lane.get(t)) * rowH;~');
DBMS_OUTPUT.PUT_LINE(q'~      const a = x(t.start);~');
DBMS_OUTPUT.PUT_LINE(q'~      const w = Math.max(1, x(t.end || t.start) - a - (rowsMode ? 0 : 1));~');
DBMS_OUTPUT.PUT_LINE(q'~      const tip = '<b>' + esc(t.name) + '</b><br>' + esc(t.type.toLowerCase()) + ' &middot; ' + esc(t.status.toLowerCase()) +~');
DBMS_OUTPUT.PUT_LINE(q'~        '<br>' + esc(fmtClock(t.start, true)) + ' &middot; ' + esc(fmtDur(t.secs)) + (t.size != null ? ' &middot; size ' + fmtN(t.size) : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~        (t.hist.length ? '<br>Histograms: ' + esc(t.hist.join(', ')) : '') + (t.error ? '<br><span class="muted">' + esc(t.error) + '</span>' : '');~');
DBMS_OUTPUT.PUT_LINE(q'~      if (rowsMode) {~');
DBMS_OUTPUT.PUT_LINE(q'~        s += '<text x="0" y="' + (y + 13) + '">' + esc(t.name.length > 42 ? t.name.slice(0, 41) + '\u2026' : t.name) + '</text>';~');
DBMS_OUTPUT.PUT_LINE(q'~        s += '<rect class="hit" x="0" y="' + y + '" width="' + (L + W) + '" height="' + rowH + '" data-tip="' + esc(tip) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~        s += '<rect class="mark ' + typeClass(t) + '" pointer-events="none" x="' + a + '" y="' + (y + 3) + '" width="' + Math.max(2, w) + '" height="' + (rowH - 6) + '" rx="2"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~      } else {~');
DBMS_OUTPUT.PUT_LINE(q'~        s += '<rect class="mark ' + typeClass(t) + '" x="' + a + '" y="' + (y + 2) + '" width="' + Math.max(1.5, w) + '" height="' + (rowH - 4) + '" data-tip="' + esc(tip) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~      }~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    tt.ticks.forEach((t) => { s += '<text x="' + x(t) + '" y="' + (H - 6) + '" text-anchor="middle">' + esc(fmtClock(t, tt.step < 5 * 60e3)) + '</text>'; });~');
DBMS_OUTPUT.PUT_LINE(q'~    s += '</svg>';~');
DBMS_OUTPUT.PUT_LINE(q'~    return { svg: s, lanes: rowsMode ? 0 : n, capped: lanes.length >= MAXL };~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // ------------------------------------------------------------ chrome~');
DBMS_OUTPUT.PUT_LINE(q'~  const app = document.getElementById('app');~');
DBMS_OUTPUT.PUT_LINE(q'~  function chrome() {~');
DBMS_OUTPUT.PUT_LINE(q'~    const scope = META.cdb === 'YES' ? (META.conId === 1 ? 'all containers (run in CDB$ROOT)' : 'PDB ' + META.con) : 'non-CDB';~');
DBMS_OUTPUT.PUT_LINE(q'~    const dbo = dbOffsetMin();~');
DBMS_OUTPUT.PUT_LINE(q'~    app.innerHTML =~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div class="top"><h1>Statistics gathering</h1>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<span class="db">' + esc(META.db || '?') + (META.dbUnique && META.dbUnique.toUpperCase() !== String(META.db).toUpperCase() ? ' (' + esc(META.dbUnique) + ')' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~      ' &middot; ' + esc(scope) + ' &middot; ' + esc(META.version || '') + ' &middot; ' + esc(META.host || '') + '</span>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<nav><a href="#overview" data-v="overview">Overview</a><a href="#runs" data-v="runs">Runs</a><a href="#backlog" data-v="backlog">Still needs stats</a><a href="#config" data-v="config">Setup</a></nav>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<span class="ctl"><label>Times <select id="tz">' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<option value="db">DB host (' + offLabel(dbo) + ')</option><option value="utc">UTC</option><option value="local">Browser (' + offLabel(-new Date().getTimezoneOffset()) + ')</option>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '</select></label><button type="button" id="theme" data-tip="Light / dark">\u25d0</button></span></div>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<main id="view"></main><div id="tip"></div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    const tz = document.getElementById('tz');~');
DBMS_OUTPUT.PUT_LINE(q'~    tz.value = tzMode;~');
DBMS_OUTPUT.PUT_LINE(q'~    tz.onchange = () => { tzMode = tz.value; if (store) store.setItem('gd.tz', tzMode); route(); };~');
DBMS_OUTPUT.PUT_LINE(q'~    const savedTheme = store && store.getItem('gd.theme');~');
DBMS_OUTPUT.PUT_LINE(q'~    if (savedTheme) document.documentElement.setAttribute('data-theme', savedTheme);~');
DBMS_OUTPUT.PUT_LINE(q'~    document.getElementById('theme').onclick = () => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const cur = document.documentElement.getAttribute('data-theme') ||~');
DBMS_OUTPUT.PUT_LINE(q'~        (window.matchMedia && matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');~');
DBMS_OUTPUT.PUT_LINE(q'~      const next = cur === 'dark' ? 'light' : 'dark';~');
DBMS_OUTPUT.PUT_LINE(q'~      document.documentElement.setAttribute('data-theme', next);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (store) store.setItem('gd.theme', next);~');
DBMS_OUTPUT.PUT_LINE(q'~    };~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // tooltips and row links (event delegation)~');
DBMS_OUTPUT.PUT_LINE(q'~  function wireGlobal() {~');
DBMS_OUTPUT.PUT_LINE(q'~    const tip = document.getElementById('tip');~');
DBMS_OUTPUT.PUT_LINE(q'~    document.addEventListener('mousemove', (e) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const el = e.target.closest && e.target.closest('[data-tip]');~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!el) { tip.style.display = 'none'; return; }~');
DBMS_OUTPUT.PUT_LINE(q'~      tip.innerHTML = el.getAttribute('data-tip');~');
DBMS_OUTPUT.PUT_LINE(q'~      tip.style.display = 'block';~');
DBMS_OUTPUT.PUT_LINE(q'~      const r = tip.getBoundingClientRect();~');
DBMS_OUTPUT.PUT_LINE(q'~      let left = e.clientX + 14, topY = e.clientY + 14;~');
DBMS_OUTPUT.PUT_LINE(q'~      if (left + r.width > innerWidth - 8) left = e.clientX - r.width - 14;~');
DBMS_OUTPUT.PUT_LINE(q'~      if (topY + r.height > innerHeight - 8) topY = e.clientY - r.height - 14;~');
DBMS_OUTPUT.PUT_LINE(q'~      tip.style.left = Math.max(4, left) + 'px';~');
DBMS_OUTPUT.PUT_LINE(q'~      tip.style.top = Math.max(4, topY) + 'px';~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    document.addEventListener('click', (e) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const el = e.target.closest && e.target.closest('[data-href]');~');
DBMS_OUTPUT.PUT_LINE(q'~      if (el && !e.target.closest('a,button,select,input')) location.hash = el.getAttribute('data-href');~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    let rt;~');
DBMS_OUTPUT.PUT_LINE(q'~    window.addEventListener('resize', () => { clearTimeout(rt); rt = setTimeout(() => route(true), 150); });~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function missingBox() {~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!missing.length) return '';~');
DBMS_OUTPUT.PUT_LINE(q'~    return '<div class="warnbox"><b>Not collected:</b> ' + missing.map(esc).join(', ') +~');
DBMS_OUTPUT.PUT_LINE(q'~      '. The SQL for these sections failed (missing grant, or an object this release does not have); the rest of the page works without them. ' +~');
DBMS_OUTPUT.PUT_LINE(q'~      'The error text is in the HTML source next to the dataset name.</div>';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function panel(title, sub, body, right) {~');
DBMS_OUTPUT.PUT_LINE(q'~    return '<section class="panel"><header><h2>' + esc(title) + '</h2>' + (sub ? '<span class="sub">' + sub + '</span>' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~      (right ? '<span class="right">' + right + '</span>' : '') + '</header>' + body + '</section>';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function tile(label, value, detail, href) {~');
DBMS_OUTPUT.PUT_LINE(q'~    return '<div class="tile"><div class="label">' + esc(label) + '</div>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      (href ? '<a class="value" href="' + esc(href) + '">' + value + '</a>' : '<div class="value">' + value + '</div>') +~');
DBMS_OUTPUT.PUT_LINE(q'~      (detail ? '<div class="detail">' + detail + '</div>' : '') + '</div>';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // ------------------------------------------------------------ overview~');
DBMS_OUTPUT.PUT_LINE(q'~  function findings() {~');
DBMS_OUTPUT.PUT_LINE(q'~    const f = [];~');
DBMS_OUTPUT.PUT_LINE(q'~    const add = (sev, html, more) => f.push({ sev: sev, html: html, more: more });~');
DBMS_OUTPUT.PUT_LINE(q'~    ATC.forEach((a) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      if (a.status !== 'ENABLED') add('crit', 'The automatic statistics task is <b>' + esc(a.status.toLowerCase()) + '</b> in ' + esc(conName(a.con)) + '.', 'Nothing gathers stale statistics there unless a custom job does.');~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    if (PREFS.get('AUTOSTATS_TARGET') === 'ORACLE') add('crit', 'AUTOSTATS_TARGET is <b>ORACLE</b> in ' + esc(META.con) + ': the automatic job gathers only Oracle-owned schemas.', 'Application schemas need their own gather jobs.');~');
DBMS_OUTPUT.PUT_LINE(q'~    const cons = [...new Set(ATC.map((a) => a.con).concat(AUTO.map((o) => o.con)))].sort((a, b) => a - b);~');
DBMS_OUTPUT.PUT_LINE(q'~    cons.forEach((c) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const runs = AUTO.filter((o) => o.con === c);~');
DBMS_OUTPUT.PUT_LINE(q'~      const la = lastAuto.get(c);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!runs.length) {~');
DBMS_OUTPUT.PUT_LINE(q'~        add('crit', 'No automatic statistics run in ' + esc(conName(c)) + ' in the last ' + DAYS + ' days.', 'Check the task status and the maintenance windows on the Setup tab.');~');
DBMS_OUTPUT.PUT_LINE(q'~        return;~');
DBMS_OUTPUT.PUT_LINE(q'~      }~');
DBMS_OUTPUT.PUT_LINE(q'~      const bad = runs.filter((o) => o.v.sev === 'crit');~');
DBMS_OUTPUT.PUT_LINE(q'~      const warn = runs.filter((o) => o.v.sev === 'warn');~');
DBMS_OUTPUT.PUT_LINE(q'~      const sec = runs.map((o) => o.secs).sort((a, b) => a - b);~');
DBMS_OUTPUT.PUT_LINE(q'~      const med = sec[Math.floor(sec.length / 2)];~');
DBMS_OUTPUT.PUT_LINE(q'~      const sev = bad.length ? 'crit' : warn.length ? 'warn' : 'good';~');
DBMS_OUTPUT.PUT_LINE(q'~      add(sev, esc(conName(c)) + ': <a href="#runs?kind=auto&con=' + c + '">' + plural(runs.length, 'automatic run') + '</a>' +~');
DBMS_OUTPUT.PUT_LINE(q'~        (bad.length ? ', <a href="#runs?kind=auto&con=' + c + '&sev=crit">' + plural(bad.length, 'did not finish', 'did not finish') + '</a>' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~        (warn.length ? ', <a href="#runs?kind=auto&con=' + c + '&sev=warn">' + fmtN(warn.length) + ' with failed objects</a>' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~        (!bad.length && !warn.length ? ', all complete' : '') + '.',~');
DBMS_OUTPUT.PUT_LINE(q'~        'Typical run ' + fmtDur(med) + ', longest ' + fmtDur(sec[sec.length - 1]) + '. Last run ' + fmtT(la.start) + ' (' + fmtAgo(la.start) + '), ' + la.v.label.toLowerCase() + '.');~');
DBMS_OUTPUT.PUT_LINE(q'~      if (GEN - la.start > 2 * DAY) add('warn', 'The last automatic run in ' + esc(conName(c)) + ' started ' + esc(fmtAgo(la.start)) + '.', 'It normally runs in every maintenance window.');~');
DBMS_OUTPUT.PUT_LINE(q'~      const wins = WINS.filter((w) => w.con === c && w.maint && !w.open && w.start >= T0 && w.end > w.start);~');
DBMS_OUTPUT.PUT_LINE(q'~      const empty = wins.filter((w) => !runs.some((o) => o.start >= w.start - 60e3 && o.start <= w.end));~');
DBMS_OUTPUT.PUT_LINE(q'~      if (empty.length) add('warn', esc(conName(c)) + ': ' + plural(empty.length, 'maintenance window') + ' of ' + fmtN(wins.length) + ' passed without an automatic statistics run.', 'Last one: ' + esc(empty[empty.length - 1].name) + ' at ' + fmtT(empty[empty.length - 1].start) + '. Windows can be too short, disabled, or taken by other tasks.');~');
DBMS_OUTPUT.PUT_LINE(q'~      const atEnd = runs.filter((o) => o.window && o.end && o.window.end - o.end < 120e3 && o.window.end > o.start);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (atEnd.length) add('crit', esc(conName(c)) + ': ' + plural(atEnd.length, 'run') + ' ended at the close of the maintenance window.', 'The window is too short for the work; objects left over wait for the next window.');~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    const rec = FAILLIST.filter((x) => x.runs.size >= 2 && !x.benign);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (rec.length) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const top = rec[0];~');
DBMS_OUTPUT.PUT_LINE(q'~      add('warn', '<a href="#overview/failures">' + plural(rec.length, 'object') + ' failed in more than one run</a>, e.g. <code>' + esc(top.target) + '</code> in ' + plural(top.runs.size, 'run') + '.', esc(top.error));~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    const ben = FAILLIST.filter((x) => x.benign);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (ben.length) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const names = [...new Set(ben.map((x) => x.target))];~');
DBMS_OUTPUT.PUT_LINE(q'~      add('info', 'Expected failures, not counted against the runs: ' + names.map((n) => '<code>' + esc(n) + '</code> (' + esc(ben.filter((x) => x.target === n).map((x) => conName(x.con)).join(', ')) + ')').join(', ') + '.', esc(ben[0].benign.why));~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    const appBL = BLAGG.filter((b) => !b.om && b.type !== 'FIXED TABLE');~');
DBMS_OUTPUT.PUT_LINE(q'~    const appStale = appBL.filter((b) => b.stale).reduce((a, b) => a + b.n, 0);~');
DBMS_OUTPUT.PUT_LINE(q'~    const appMissing = appBL.filter((b) => b.missing && b.type !== 'SUBPARTITION').reduce((a, b) => a + b.n, 0);~');
DBMS_OUTPUT.PUT_LINE(q'~    const cnt = {};~');
DBMS_OUTPUT.PUT_LINE(q'~    BL.filter((b) => !b.om).forEach((b) => { cnt[b.cat] = (cnt[b.cat] || 0) + 1; });~');
DBMS_OUTPUT.PUT_LINE(q'~    if (cnt.missed || cnt.failed) {~');
DBMS_OUTPUT.PUT_LINE(q'~      add('crit', '<a href="#backlog?cat=' + (cnt.missed ? 'missed' : 'failed') + '">' + (cnt.missed ? plural(cnt.missed, 'application object') + ' missed by the last automatic run' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~        (cnt.missed && cnt.failed ? ', ' : '') + (cnt.failed ? plural(cnt.failed, 'object') + ' whose last gather failed' : '') + '</a>.', 'They are stale now, and the job had its chance.');~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    if (appStale || appMissing) {~');
DBMS_OUTPUT.PUT_LINE(q'~      add('info', 'Application objects needing statistics now: <a href="#backlog">' + fmtN(appStale) + ' stale, ' + fmtN(appMissing) + ' without statistics</a>.',~');
DBMS_OUTPUT.PUT_LINE(q'~        (cnt.fresh ? fmtN(cnt.fresh) + ' changed after the last automatic run (expected). ' : '') + (cnt.locked ? fmtN(cnt.locked) + ' locked. ' : '') + 'Staleness as of the last DML-monitoring flush.');~');
DBMS_OUTPUT.PUT_LINE(q'~    } else if (!missing.includes('bl')) {~');
DBMS_OUTPUT.PUT_LINE(q'~      add('good', 'No application table or partition is stale or missing statistics right now.');~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    const mf = GATHERS.filter((o) => o.v.sev === 'crit');~');
DBMS_OUTPUT.PUT_LINE(q'~    if (GATHERS.length) add(mf.length ? 'warn' : 'good', '<a href="#runs?kind=gather">' + plural(GATHERS.length, 'manual or custom gather') + '</a>' + (mf.length ? ', <a href="#runs?kind=gather&sev=crit">' + fmtN(mf.length) + ' failed</a>' : ', none failed') + '.');~');
DBMS_OUTPUT.PUT_LINE(q'~    return f.sort((a, b) => SEV_RANK[b.sev] - SEV_RANK[a.sev]);~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function viewOverview(sub) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const v = document.getElementById('view');~');
DBMS_OUTPUT.PUT_LINE(q'~    const runsOk = AUTO.filter((o) => o.v.sev === 'good').length;~');
DBMS_OUTPUT.PUT_LINE(q'~    const objs = AUTO.reduce((a, o) => a + o.stats.done, 0) + GATHERS.reduce((a, o) => a + o.stats.done, 0);~');
DBMS_OUTPUT.PUT_LINE(q'~    const failedObjs = new Set(FAILLIST.filter((f) => !f.benign).map((f) => f.con + '|' + f.target)).size;~');
DBMS_OUTPUT.PUT_LINE(q'~    const benignObjs = new Set(FAILLIST.filter((f) => f.benign).map((f) => f.con + '|' + f.target)).size;~');
DBMS_OUTPUT.PUT_LINE(q'~    const totalSecs = AUTO.concat(GATHERS).reduce((a, o) => a + o.secs, 0);~');
DBMS_OUTPUT.PUT_LINE(q'~    const longest = AUTO.reduce((m, o) => (!m || o.secs > m.secs ? o : m), null);~');
DBMS_OUTPUT.PUT_LINE(q'~    const appBL = BLAGG.filter((b) => !b.om && b.type !== 'FIXED TABLE');~');
DBMS_OUTPUT.PUT_LINE(q'~    const stale = appBL.filter((b) => b.stale).reduce((a, b) => a + b.n, 0);~');
DBMS_OUTPUT.PUT_LINE(q'~    const miss = appBL.filter((b) => b.missing && b.type !== 'SUBPARTITION').reduce((a, b) => a + b.n, 0);~');
DBMS_OUTPUT.PUT_LINE(q'~    const hist = AUTO.concat(GATHERS).reduce((a, o) => a + o.stats.hist, 0);~');
DBMS_OUTPUT.PUT_LINE(q'~    let h = missingBox();~');
DBMS_OUTPUT.PUT_LINE(q'~    h += panel('Findings', 'last ' + DAYS + ' days to ' + esc(fmtT(GEN)) + ' &middot; times in ' + esc(tzMode === 'utc' ? 'UTC' : offLabel(tzOff(GEN))),~');
DBMS_OUTPUT.PUT_LINE(q'~      '<ul class="findings">' + findings().map((x) => '<li>' + sevBadge(x.sev, '') + '<div>' + x.html + (x.more ? '<div class="more">' + x.more + '</div>' : '') + '</div></li>').join('') + '</ul>');~');
DBMS_OUTPUT.PUT_LINE(q'~    h += '<div class="tiles" style="margin-bottom:16px">' +~');
DBMS_OUTPUT.PUT_LINE(q'~      tile('Automatic runs', fmtN(AUTO.length), fmtN(runsOk) + ' complete, ' + fmtN(AUTO.length - runsOk) + ' with problems', '#runs?kind=auto') +~');
DBMS_OUTPUT.PUT_LINE(q'~      tile('Manual / custom gathers', fmtN(GATHERS.length), fmtN(GATHERS.filter((o) => o.v.sev === 'crit').length) + ' failed', '#runs?kind=gather') +~');
DBMS_OUTPUT.PUT_LINE(q'~      tile('Objects gathered', compact(objs), 'tables, partitions, indexes; ' + compact(hist) + ' with histograms') +~');
DBMS_OUTPUT.PUT_LINE(q'~      tile('Objects that failed', fmtN(failedObjs), 'distinct objects' + (benignObjs ? ', plus ' + fmtN(benignObjs) + ' expected' : ''), '#overview/failures') +~');
DBMS_OUTPUT.PUT_LINE(q'~      tile('Time spent gathering', fmtDur(totalSecs), longest ? 'longest automatic run ' + fmtDur(longest.secs) : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~      tile('Stale now', fmtN(stale), 'application tables / partitions', '#backlog') +~');
DBMS_OUTPUT.PUT_LINE(q'~      tile('Without statistics', fmtN(miss), 'application tables / partitions', '#backlog?cat=missing') +~');
DBMS_OUTPUT.PUT_LINE(q'~      '</div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    const cons = [...new Set(OPS.filter((o) => o.kind !== 'other').map((o) => o.con))].sort((a, b) => a - b);~');
DBMS_OUTPUT.PUT_LINE(q'~    h += panel('Timeline', 'each mark is one run; click for its detail',~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div id="tl"></div><div class="legend"><span><b class="win"></b>maintenance window</span><span><b class="good"></b>complete</span><span><b class="warn"></b>some objects failed</span><span><b class="crit"></b>failed, stopped or not finished</span></div>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<h3 class="chart-title">Automatic job: run time per run</h3><div id="c-dur"></div>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<h3 class="chart-title">Automatic job: objects per run</h3><div id="c-obj"></div>' + consLegend());~');
DBMS_OUTPUT.PUT_LINE(q'~    h += panel('Failures', 'same object, same error, across runs', '<div id="t-fail"></div>');~');
DBMS_OUTPUT.PUT_LINE(q'~    h += panel('Most expensive objects', 'total gather time in the period', '<div id="t-heavy"></div>');~');
DBMS_OUTPUT.PUT_LINE(q'~    v.innerHTML = h;~');
DBMS_OUTPUT.PUT_LINE(q'~    const w = v.querySelector('#tl').clientWidth;~');
DBMS_OUTPUT.PUT_LINE(q'~    v.querySelector('#tl').innerHTML = cons.length ? timelineSVG(w, T0, GEN, cons) : '<p class="note">No gather operations in the period.</p>';~');
DBMS_OUTPUT.PUT_LINE(q'~    const autoSorted = AUTO.slice().sort((a, b) => a.start - b.start);~');
DBMS_OUTPUT.PUT_LINE(q'~    const cw = w;~');
DBMS_OUTPUT.PUT_LINE(q'~    v.querySelector('#c-dur').innerHTML = autoSorted.length ? runColumnsSVG(cw, T0, GEN, autoSorted, (o) => o.secs, fmtDur, 'Run time per automatic run') : '<p class="note">No automatic runs.</p>';~');
DBMS_OUTPUT.PUT_LINE(q'~    v.querySelector('#c-obj').innerHTML = autoSorted.length ? runColumnsSVG(cw, T0, GEN, autoSorted, (o) => o.stats.n, compact, 'Objects per automatic run') : '';~');
DBMS_OUTPUT.PUT_LINE(q'~    renderTable(v.querySelector('#t-fail'), {~');
DBMS_OUTPUT.PUT_LINE(q'~      rows: FAILLIST, sort: ['runs', -1], limit: sub === 'failures' ? 1000 : 10, empty: 'No object failed in the period.',~');
DBMS_OUTPUT.PUT_LINE(q'~      href: (f) => '#run/' + f.lastOp.key,~');
DBMS_OUTPUT.PUT_LINE(q'~      cols: [~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'target', label: 'Object', html: (f) => '<code>' + esc(f.target) + '</code>' + (CONS.size > 1 ? ' <span class="pill">' + esc(conName(f.con)) + '</span>' : '') },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'runs', label: 'Runs', num: true, val: (f) => f.runs.size, html: (f) => fmtN(f.runs.size) },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'last', label: 'Last', cls: 't', html: (f) => esc(fmtT(f.last)) },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'error', label: 'Error', cls: 'wrap', html: (f) => (f.benign ? '<span class="pill" data-tip="' + esc(esc(f.benign.why)) + '">expected</span> ' + esc(f.error) : '<span class="err">' + esc(f.error) + '</span>') }~');
DBMS_OUTPUT.PUT_LINE(q'~      ]~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    if (sub === 'failures') v.querySelector('#t-fail').scrollIntoView();~');
DBMS_OUTPUT.PUT_LINE(q'~    const heavy = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~    TASKS.forEach((t) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!t.op || t.op.kind === 'other' || t.secs == null) return;~');
DBMS_OUTPUT.PUT_LINE(q'~      const k = t.con + '|' + t.name;~');
DBMS_OUTPUT.PUT_LINE(q'~      let x = heavy.get(k);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!x) heavy.set(k, x = { con: t.con, name: t.name, type: t.type, n: 0, secs: 0, max: 0, last: null });~');
DBMS_OUTPUT.PUT_LINE(q'~      x.n++; x.secs += t.secs; x.max = Math.max(x.max, t.secs);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!x.last || t.start > x.last.start) x.last = t;~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    const hl = [...heavy.values()].sort((a, b) => b.secs - a.secs).slice(0, 200);~');
DBMS_OUTPUT.PUT_LINE(q'~    const hmax = hl.length ? hl[0].secs : 1;~');
DBMS_OUTPUT.PUT_LINE(q'~    renderTable(v.querySelector('#t-heavy'), {~');
DBMS_OUTPUT.PUT_LINE(q'~      rows: hl, sort: ['secs', -1], limit: 10, empty: 'No per-object timings recorded.',~');
DBMS_OUTPUT.PUT_LINE(q'~      href: (x) => '#run/' + x.last.op.key,~');
DBMS_OUTPUT.PUT_LINE(q'~      cols: [~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'name', label: 'Object', html: (x) => '<code>' + esc(x.name) + '</code> <span class="pill">' + esc(x.type.toLowerCase()) + '</span>' },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'n', label: 'Gathers', num: true, html: (x) => fmtN(x.n) },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'secs', label: 'Total', num: true, html: (x) => esc(fmtDur(x.secs)) },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'bar', label: '', val: (x) => x.secs, html: (x) => '<div class="bar"><b style="width:' + (100 * x.secs / hmax).toFixed(1) + '%"></b></div>' },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'max', label: 'Longest', num: true, html: (x) => esc(fmtDur(x.max)) }~');
DBMS_OUTPUT.PUT_LINE(q'~      ]~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function consLegend() {~');
DBMS_OUTPUT.PUT_LINE(q'~    const cons = [...new Set(AUTO.map((o) => o.con))].sort((a, b) => a - b);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (cons.length < 2) return '';~');
DBMS_OUTPUT.PUT_LINE(q'~    return '<div class="legend">' + cons.map((c, i) => '<span><b class="s' + (i % 3 + 1) + '"></b>' + esc(conName(c)) + '</span>').join('') + '</div>';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // ------------------------------------------------------------ runs~');
DBMS_OUTPUT.PUT_LINE(q'~  function viewRuns(q) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const v = document.getElementById('view');~');
DBMS_OUTPUT.PUT_LINE(q'~    const f = {~');
DBMS_OUTPUT.PUT_LINE(q'~      kind: q.get('kind') || 'gathers', con: q.get('con') || '', sev: q.get('sev') || '', text: q.get('q') || ''~');
DBMS_OUTPUT.PUT_LINE(q'~    };~');
DBMS_OUTPUT.PUT_LINE(q'~    const consAll = [...new Set(OPS.map((o) => o.con))].sort((a, b) => a - b);~');
END;
/
BEGIN
DBMS_OUTPUT.PUT_LINE(q'~    v.innerHTML = missingBox() + panel('Runs', 'every DBMS_STATS operation in the last ' + DAYS + ' days; click a row for its objects',~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div class="filters">' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<label>Show <select id="f-kind"><option value="gathers">All gathers</option><option value="auto">Automatic job</option><option value="gather">Manual / custom gathers</option><option value="all">All DBMS_STATS operations</option></select></label>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      (consAll.length > 1 ? '<label>Container <select id="f-con"><option value="">All</option>' + consAll.map((c) => '<option value="' + c + '">' + esc(conName(c)) + '</option>').join('') + '</select></label>' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<label>Outcome <select id="f-sev"><option value="">Any</option><option value="crit">Failed / not finished</option><option value="warn">Some objects failed</option><option value="problem">Any problem</option><option value="good">Complete</option></select></label>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<input type="search" id="f-q" placeholder="Filter: operation, target, job, error" size="34">' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<span class="note" id="f-n"></span></div><div id="t-runs"></div>');~');
DBMS_OUTPUT.PUT_LINE(q'~    const sel = (id) => v.querySelector(id);~');
DBMS_OUTPUT.PUT_LINE(q'~    sel('#f-kind').value = f.kind;~');
DBMS_OUTPUT.PUT_LINE(q'~    if (sel('#f-con')) sel('#f-con').value = f.con;~');
DBMS_OUTPUT.PUT_LINE(q'~    sel('#f-sev').value = f.sev;~');
DBMS_OUTPUT.PUT_LINE(q'~    sel('#f-q').value = f.text;~');
DBMS_OUTPUT.PUT_LINE(q'~    const host = sel('#t-runs');~');
DBMS_OUTPUT.PUT_LINE(q'~    function apply() {~');
DBMS_OUTPUT.PUT_LINE(q'~      f.kind = sel('#f-kind').value; f.con = sel('#f-con') ? sel('#f-con').value : ''; f.sev = sel('#f-sev').value; f.text = sel('#f-q').value.trim().toLowerCase();~');
DBMS_OUTPUT.PUT_LINE(q'~      const params = new URLSearchParams();~');
DBMS_OUTPUT.PUT_LINE(q'~      if (f.kind !== 'gathers') params.set('kind', f.kind);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (f.con) params.set('con', f.con);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (f.sev) params.set('sev', f.sev);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (f.text) params.set('q', f.text);~');
DBMS_OUTPUT.PUT_LINE(q'~      const hs = '#runs' + (params.toString() ? '?' + params.toString() : '');~');
DBMS_OUTPUT.PUT_LINE(q'~      if (location.hash !== hs) history.replaceState(null, '', hs);~');
DBMS_OUTPUT.PUT_LINE(q'~      const list = OPS.filter((o) =>~');
DBMS_OUTPUT.PUT_LINE(q'~        (f.kind === 'all' || (f.kind === 'gathers' ? o.kind !== 'other' : o.kind === f.kind)) &&~');
DBMS_OUTPUT.PUT_LINE(q'~        (!f.con || String(o.con) === f.con) &&~');
DBMS_OUTPUT.PUT_LINE(q'~        (!f.sev || (f.sev === 'problem' ? o.v.sev === 'crit' || o.v.sev === 'warn' : o.v.sev === f.sev)) &&~');
DBMS_OUTPUT.PUT_LINE(q'~        (!f.text || [o.op, opTarget(o), o.job, o.error, o.status, o.v.label].join(' ').toLowerCase().includes(f.text)));~');
DBMS_OUTPUT.PUT_LINE(q'~      sel('#f-n').textContent = plural(list.length, 'operation');~');
DBMS_OUTPUT.PUT_LINE(q'~      host._t = host._t || { sort: ['start', -1], limit: 300 };~');
DBMS_OUTPUT.PUT_LINE(q'~      renderTable(host, {~');
DBMS_OUTPUT.PUT_LINE(q'~        rows: list, href: (o) => '#run/' + o.key, empty: 'No operation matches.',~');
DBMS_OUTPUT.PUT_LINE(q'~        cols: [~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'start', label: 'Started', cls: 't', desc: true, html: (o) => esc(fmtT(o.start, true)) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'sev', label: 'Outcome', val: (o) => SEV_RANK[o.v.sev], desc: true, html: (o) => sevBadge(o.v.sev, o.v.label, o.v.why) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'con', label: 'Container', html: (o) => esc(conName(o.con)) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'op', label: 'Operation', val: (o) => opLabel(o), html: (o) => esc(opLabel(o)) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'target', label: 'Target', cls: 'wrap', val: (o) => opTarget(o), html: (o) => '<code>' + esc(opTarget(o)) + '</code>' },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'secs', label: 'Duration', num: true, html: (o) => esc(fmtDur(o.secs)) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'n', label: 'Objects', num: true, val: (o) => o.stats.n, html: (o) => (o.stats.n ? fmtN(o.stats.n) : '') },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'failed', label: 'Failed', num: true, val: (o) => o.stats.failed + o.stats.notDone, html: (o) => (o.stats.failed + o.stats.notDone ? '<span class="err">' + fmtN(o.stats.failed + o.stats.notDone) + '</span>' : '') },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'job', label: 'Job / window', html: (o) => esc(o.job || '') + (o.window ? ' <span class="pill">' + esc(o.window.name) + '</span>' : '') }~');
DBMS_OUTPUT.PUT_LINE(q'~        ]~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    ['#f-kind', '#f-con', '#f-sev'].forEach((id) => { if (sel(id)) sel(id).onchange = () => { host._t.limit = 300; apply(); }; });~');
DBMS_OUTPUT.PUT_LINE(q'~    let qt;~');
DBMS_OUTPUT.PUT_LINE(q'~    sel('#f-q').oninput = () => { clearTimeout(qt); qt = setTimeout(apply, 200); };~');
DBMS_OUTPUT.PUT_LINE(q'~    apply();~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // ------------------------------------------------------------ one run~');
DBMS_OUTPUT.PUT_LINE(q'~  function viewRun(con, id) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const v = document.getElementById('view');~');
DBMS_OUTPUT.PUT_LINE(q'~    const o = OPMAP.get(con + '/' + id);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!o) { v.innerHTML = panel('Run not found', '', '<p>No operation ' + esc(id) + ' in container ' + esc(con) + ' in this report.</p>'); return; }~');
DBMS_OUTPUT.PUT_LINE(q'~    const s = o.stats;~');
DBMS_OUTPUT.PUT_LINE(q'~    const same = OPS.filter((x) => x.kind === o.kind && x.con === o.con && (o.kind !== 'gather' || x.op === o.op)).sort((a, b) => a.start - b.start);~');
DBMS_OUTPUT.PUT_LINE(q'~    const i = same.indexOf(o);~');
DBMS_OUTPUT.PUT_LINE(q'~    const prev = same[i - 1], next = same[i + 1];~');
DBMS_OUTPUT.PUT_LINE(q'~    let h = '<div class="crumbs"><a href="#runs?kind=' + (o.kind === 'other' ? 'all' : o.kind) + '">\u2190 Runs</a>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      (prev ? ' &middot; <a href="#run/' + prev.key + '">previous</a>' : '') + (next ? ' &middot; <a href="#run/' + next.key + '">next</a>' : '') + '</div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    h += '<div class="title-row"><h2>' + esc(opLabel(o)) + (o.kind === 'auto' ? '' : ' <code>' + esc(opTarget(o)) + '</code>') + '</h2>' + sevBadge(o.v.sev, o.v.label) +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<span class="note">' + esc(conName(o.con)) + ' &middot; operation ' + esc(o.id) + '</span></div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.v.sev !== 'good') h += '<div class="warnbox">' + esc(o.v.why) + '</div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    const facts = [~');
DBMS_OUTPUT.PUT_LINE(q'~      ['Started', fmtT(o.start, true)],~');
DBMS_OUTPUT.PUT_LINE(q'~      ['Ended', o.end ? fmtT(o.end, true) : '(no end recorded)'],~');
DBMS_OUTPUT.PUT_LINE(q'~      ['Duration', fmtDur(o.secs)],~');
DBMS_OUTPUT.PUT_LINE(q'~      ['Status', o.status],~');
DBMS_OUTPUT.PUT_LINE(q'~      ['Job', o.job || '(called from a session, not a scheduler job)'],~');
DBMS_OUTPUT.PUT_LINE(q'~      ['Session', o.sid]~');
DBMS_OUTPUT.PUT_LINE(q'~    ];~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.sjr) facts.push(['Scheduler', o.sjr.status + ' &middot; run ' + fmtDur(o.sjr.secs) + ' &middot; CPU ' + fmtDur(o.sjr.cpu) + (o.sjr.error ? ' &middot; ORA-' + o.sjr.error : '')]);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.window) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const used = o.end && o.window.end > o.window.start ? (100 * (o.end - o.window.start)) / (o.window.end - o.window.start) : null;~');
DBMS_OUTPUT.PUT_LINE(q'~      facts.push(['Window', o.window.name + ' ' + fmtT(o.window.start) + ' \u2192 ' + fmtClock(o.window.end) + ' (' + fmtDur(o.window.secs) + ')' +~');
DBMS_OUTPUT.PUT_LINE(q'~        (o.end ? ' &middot; ended ' + fmtDur((o.window.end - o.end) / 1000) + ' before the window closed' : '') + (used != null ? ' &middot; ' + used.toFixed(0) + '% of the window elapsed' : '')]);~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.ajh && o.ajh.info) facts.push(['Job info', o.ajh.info]);~');
DBMS_OUTPUT.PUT_LINE(q'~    const kv = '<dl class="kv">' + facts.map((f) => '<dt>' + esc(f[0]) + '</dt><dd>' + (f[0] === 'Scheduler' || f[0] === 'Window' ? f[1] : esc(f[1])) + '</dd>').join('') + '</dl>';~');
DBMS_OUTPUT.PUT_LINE(q'~    const pk = Object.keys(o.params);~');
DBMS_OUTPUT.PUT_LINE(q'~    const params = pk.length ? '<dl class="kv">' + pk.map((k) => '<dt>' + esc(k) + '</dt><dd><code>' + esc(o.params[k] === '' ? "''" : o.params[k]) + '</code></dd>').join('') + '</dl>' : '<p class="note">No parameters recorded.</p>';~');
DBMS_OUTPUT.PUT_LINE(q'~    h += '<div class="cols">' + panel('Run', '', kv + (o.error ? '<div class="err-block" style="margin-top:10px">' + esc(o.error) + '</div>' : '')) +~');
DBMS_OUTPUT.PUT_LINE(q'~      panel('Parameters', 'as the call resolved them (DEFAULT_* = the preference in force)', params) + '</div><div style="height:16px"></div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    if (s.n) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const types = Object.keys(s.byType).sort((a, b) => s.byType[b].secs - s.byType[a].secs);~');
DBMS_OUTPUT.PUT_LINE(q'~      let tb = '<div class="tablewrap"><table><thead><tr><th>Object type</th><th class="num">Objects</th><th class="num">Gathered</th><th class="num">Failed</th><th class="num">Not processed</th><th class="num">With histograms</th><th class="num">Time (sum)</th></tr></thead><tbody>';~');
DBMS_OUTPUT.PUT_LINE(q'~      types.forEach((t) => {~');
DBMS_OUTPUT.PUT_LINE(q'~        const b = s.byType[t];~');
DBMS_OUTPUT.PUT_LINE(q'~        tb += '<tr><td>' + esc(t.toLowerCase()) + '</td><td class="num">' + fmtN(b.n) + '</td><td class="num">' + fmtN(b.done) + '</td><td class="num">' + (b.failed ? '<span class="err">' + fmtN(b.failed) + '</span>' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~          '</td><td class="num">' + (b.other ? '<span class="err">' + fmtN(b.other) + '</span>' : '') + '</td><td class="num">' + (b.hist ? fmtN(b.hist) : '') + '</td><td class="num">' + esc(fmtDur(b.secs)) + '</td></tr>';~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~      tb += '<tr><td><b>Total</b></td><td class="num"><b>' + fmtN(s.n) + '</b></td><td class="num">' + fmtN(s.done) + '</td><td class="num">' + (s.failed ? '<span class="err">' + fmtN(s.failed) + '</span>' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~        '</td><td class="num">' + (s.notDone ? '<span class="err">' + fmtN(s.notDone) + '</span>' : '') + '</td><td class="num">' + fmtN(s.hist) + '</td><td class="num">' + esc(fmtDur(s.secs)) + '</td></tr></tbody></table></div>';~');
DBMS_OUTPUT.PUT_LINE(q'~      const conc = o.params.concurrent === 'TRUE' || (s.secs > o.secs * 1.2 && o.secs > 1);~');
DBMS_OUTPUT.PUT_LINE(q'~      const owners = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~      o.tasks.forEach((t) => { const k = t.parts[0] || '?'; const x = owners.get(k) || { n: 0, secs: 0 }; x.n++; x.secs += t.secs || 0; owners.set(k, x); });~');
DBMS_OUTPUT.PUT_LINE(q'~      const ol = [...owners.entries()].sort((a, b) => b[1].secs - a[1].secs).slice(0, 8);~');
DBMS_OUTPUT.PUT_LINE(q'~      const ot = '<div class="tablewrap"><table><thead><tr><th>Schema</th><th class="num">Objects</th><th class="num">Time (sum)</th></tr></thead><tbody>' +~');
DBMS_OUTPUT.PUT_LINE(q'~        ol.map((e) => '<tr><td>' + esc(e[0]) + '</td><td class="num">' + fmtN(e[1].n) + '</td><td class="num">' + esc(fmtDur(e[1].secs)) + '</td></tr>').join('') + '</tbody></table></div>';~');
DBMS_OUTPUT.PUT_LINE(q'~      h += '<div class="cols cols-2-1">' + panel('What it did', plural(s.n, 'object') + (conc ? ' &middot; objects ran concurrently, so the sum exceeds the elapsed time' : ''), tb) +~');
DBMS_OUTPUT.PUT_LINE(q'~        panel('By schema', o.truncated ? 'from the ' + fmtN(o.tasks.length) + ' objects embedded' : '', ot) + '</div><div style="height:16px"></div>';~');
DBMS_OUTPUT.PUT_LINE(q'~      h += panel('Objects over time', (o.tasks.length > 40 ? 'objects running at the same time stack into lanes; hover for each object' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~        (o.window && o.window.end <= o.endEff + 60e3 ? ' &middot; red line: window end' : ''),~');
DBMS_OUTPUT.PUT_LINE(q'~        '<div id="gantt"></div><div class="legend"><span><b class="s1"></b>table</span><span><b class="s2"></b>partition</span><span><b class="s3"></b>index</span><span><b class="crit"></b>failed</span><span><b class="warn"></b>not completed</span></div>');~');
DBMS_OUTPUT.PUT_LINE(q'~      h += panel('Objects', o.truncated ? 'showing ' + fmtN(o.tasks.length) + ' of ' + fmtN(s.n) + ' (failed first, then slowest; raise max_tasks_per_run for all)' : plural(s.n, 'object'),~');
DBMS_OUTPUT.PUT_LINE(q'~        '<div class="filters"><label>Status <select id="o-st"><option value="">Any</option>' + [...new Set(o.tasks.map((t) => t.status))].sort().map((x) => '<option>' + esc(x) + '</option>').join('') + '</select></label>' +~');
DBMS_OUTPUT.PUT_LINE(q'~        '<label>Type <select id="o-ty"><option value="">Any</option>' + [...new Set(o.tasks.map((t) => t.type))].sort().map((x) => '<option>' + esc(x) + '</option>').join('') + '</select></label>' +~');
DBMS_OUTPUT.PUT_LINE(q'~        '<input type="search" id="o-q" placeholder="Filter objects" size="28"></div><div id="t-obj"></div>');~');
DBMS_OUTPUT.PUT_LINE(q'~    } else if (o.kind !== 'other') {~');
DBMS_OUTPUT.PUT_LINE(q'~      h += panel('What it did', '', '<p>No per-object rows recorded for this operation' + (o.status === 'COMPLETED' ? ': it found nothing to gather.' : '.') + '</p>');~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.kind === 'auto' && lastAuto.get(o.con) === o) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const n = BL.filter((b) => b.con === o.con && !b.om && (b.cat === 'missed' || b.cat === 'failed')).length;~');
DBMS_OUTPUT.PUT_LINE(q'~      h += panel('After this run', 'the latest automatic run in ' + esc(conName(o.con)),~');
DBMS_OUTPUT.PUT_LINE(q'~        '<p>' + (n ? '<a href="#backlog?cat=missed&con=' + o.con + '">' + plural(n, 'application object') + '</a> were stale before this run started and are still stale, or failed.' : 'No application object that was stale when this run started is still stale.') + '</p>');~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    v.innerHTML = h;~');
DBMS_OUTPUT.PUT_LINE(q'~    if (s.n && o.tasks.length) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const g = v.querySelector('#gantt');~');
DBMS_OUTPUT.PUT_LINE(q'~      const gr = ganttSVG(g.clientWidth, o, o.tasks);~');
DBMS_OUTPUT.PUT_LINE(q'~      g.innerHTML = gr.svg + (gr.capped ? '<p class="note">More than 24 objects ran at once; the busiest lanes are merged.</p>' : '');~');
DBMS_OUTPUT.PUT_LINE(q'~      const host = v.querySelector('#t-obj');~');
DBMS_OUTPUT.PUT_LINE(q'~      const st = v.querySelector('#o-st'), ty = v.querySelector('#o-ty'), qq = v.querySelector('#o-q');~');
DBMS_OUTPUT.PUT_LINE(q'~      const draw = () => {~');
DBMS_OUTPUT.PUT_LINE(q'~        const q = qq.value.trim().toLowerCase();~');
DBMS_OUTPUT.PUT_LINE(q'~        renderTable(host, {~');
DBMS_OUTPUT.PUT_LINE(q'~          rows: o.tasks.filter((t) => (!st.value || t.status === st.value) && (!ty.value || t.type === ty.value) && (!q || (t.name + ' ' + (t.error || '') + ' ' + t.hist.join(' ')).toLowerCase().includes(q))),~');
DBMS_OUTPUT.PUT_LINE(q'~          sort: ['secs', -1], limit: 300,~');
DBMS_OUTPUT.PUT_LINE(q'~          cols: [~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'name', label: 'Object', html: (t) => '<code>' + esc(t.name) + '</code>' },~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'type', label: 'Type', html: (t) => esc(t.type.toLowerCase()) },~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'size', label: 'Size', num: true, tip: 'TARGET_SIZE as recorded by DBMS_STATS (blocks)', html: (t) => fmtN(t.size) },~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'start', label: 'Started', cls: 't', html: (t) => esc(fmtClock(t.start, true)) },~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'secs', label: 'Duration', num: true, html: (t) => esc(fmtDur(t.secs)) },~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'status', label: 'Status', html: (t) => (t.status === 'COMPLETED' ? sevBadge('good', 'gathered') : sevBadge(t.status === 'FAILED' ? 'crit' : 'warn', t.status.toLowerCase())) },~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'hist', label: 'Histograms', cls: 'wrap', val: (t) => t.hist.length, html: (t) => (t.hist.length ? '<span data-tip="' + esc(esc(t.hist.join(', '))) + '">' + plural(t.hist.length, 'column') + '</span>' : '') },~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'error', label: 'Error / extended stats', cls: 'wrap', html: (t) => (t.error ? '<span class="err">' + esc(t.error) + '</span>' : esc(t.xstats)) }~');
DBMS_OUTPUT.PUT_LINE(q'~          ]~');
DBMS_OUTPUT.PUT_LINE(q'~        });~');
DBMS_OUTPUT.PUT_LINE(q'~      };~');
DBMS_OUTPUT.PUT_LINE(q'~      [st, ty].forEach((e) => { e.onchange = () => { host._t.limit = 300; draw(); }; });~');
DBMS_OUTPUT.PUT_LINE(q'~      let qt;~');
DBMS_OUTPUT.PUT_LINE(q'~      qq.oninput = () => { clearTimeout(qt); qt = setTimeout(draw, 200); };~');
DBMS_OUTPUT.PUT_LINE(q'~      draw();~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // ------------------------------------------------------------ backlog~');
DBMS_OUTPUT.PUT_LINE(q'~  function viewBacklog(q) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const v = document.getElementById('view');~');
DBMS_OUTPUT.PUT_LINE(q'~    const f = { cat: q.get('cat') || '', con: q.get('con') || '', om: q.get('om') === '1', text: q.get('q') || '' };~');
DBMS_OUTPUT.PUT_LINE(q'~    const consAll = [...new Set(BL.map((b) => b.con))].sort((a, b) => a - b);~');
DBMS_OUTPUT.PUT_LINE(q'~    let h = missingBox();~');
DBMS_OUTPUT.PUT_LINE(q'~    h += '<div class="cat-cards" id="cats"></div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    h += panel('Objects that need statistics now', 'tables, partitions and subpartitions that are stale or have no statistics; staleness as of the last DML-monitoring flush',~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div class="filters">' +~');
DBMS_OUTPUT.PUT_LINE(q'~      (consAll.length > 1 ? '<label>Container <select id="b-con"><option value="">All</option>' + consAll.map((c) => '<option value="' + c + '">' + esc(conName(c)) + '</option>').join('') + '</select></label>' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<label><input type="checkbox" id="b-om"> include Oracle-maintained schemas</label>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<input type="search" id="b-q" placeholder="Filter: owner, table, partition" size="30">' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<span class="note" id="b-n"></span></div>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      (blTruncated ? '<p class="note">Only the first ' + fmtN(BL.length) + ' objects are embedded (application schemas first); raise max_backlog for all. The counts on the cards cover the embedded rows.</p>' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div id="t-bl"></div>');~');
DBMS_OUTPUT.PUT_LINE(q'~    v.innerHTML = h;~');
DBMS_OUTPUT.PUT_LINE(q'~    const sel = (id) => v.querySelector(id);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (sel('#b-con')) sel('#b-con').value = f.con;~');
DBMS_OUTPUT.PUT_LINE(q'~    sel('#b-om').checked = f.om;~');
DBMS_OUTPUT.PUT_LINE(q'~    sel('#b-q').value = f.text;~');
DBMS_OUTPUT.PUT_LINE(q'~    const host = sel('#t-bl');~');
DBMS_OUTPUT.PUT_LINE(q'~    function apply() {~');
DBMS_OUTPUT.PUT_LINE(q'~      f.con = sel('#b-con') ? sel('#b-con').value : '';~');
DBMS_OUTPUT.PUT_LINE(q'~      f.om = sel('#b-om').checked;~');
DBMS_OUTPUT.PUT_LINE(q'~      f.text = sel('#b-q').value.trim().toLowerCase();~');
DBMS_OUTPUT.PUT_LINE(q'~      const params = new URLSearchParams();~');
DBMS_OUTPUT.PUT_LINE(q'~      if (f.cat) params.set('cat', f.cat);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (f.con) params.set('con', f.con);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (f.om) params.set('om', '1');~');
DBMS_OUTPUT.PUT_LINE(q'~      if (f.text) params.set('q', f.text);~');
DBMS_OUTPUT.PUT_LINE(q'~      const hs = '#backlog' + (params.toString() ? '?' + params.toString() : '');~');
DBMS_OUTPUT.PUT_LINE(q'~      if (location.hash !== hs) history.replaceState(null, '', hs);~');
DBMS_OUTPUT.PUT_LINE(q'~      const base = BL.filter((b) => (f.om || !b.om) && (!f.con || String(b.con) === f.con) && (!f.text || b.name.toLowerCase().includes(f.text)));~');
DBMS_OUTPUT.PUT_LINE(q'~      const cnt = {};~');
DBMS_OUTPUT.PUT_LINE(q'~      base.forEach((b) => { cnt[b.cat] = (cnt[b.cat] || 0) + 1; });~');
DBMS_OUTPUT.PUT_LINE(q'~      sel('#cats').innerHTML = CAT_ORDER.filter((c) => cnt[c] || f.cat === c).map((c) =>~');
DBMS_OUTPUT.PUT_LINE(q'~        '<button type="button" class="cat-card' + (f.cat === c ? ' on' : '') + '" data-cat="' + c + '"><div>' + sevBadge(CATS[c].sev, CATS[c].title) + '</div><div class="n">' + fmtN(cnt[c] || 0) + '</div><div class="d">' + esc(CATS[c].text) + '</div></button>').join('') ||~');
DBMS_OUTPUT.PUT_LINE(q'~        '<div class="tile"><div class="label">Nothing needs statistics</div><div class="detail">with the current filters</div></div>';~');
DBMS_OUTPUT.PUT_LINE(q'~      sel('#cats').querySelectorAll('[data-cat]').forEach((b) => {~');
DBMS_OUTPUT.PUT_LINE(q'~        b.onclick = () => { const c = b.getAttribute('data-cat'); f.cat = f.cat === c ? '' : c; host._t && (host._t.limit = 300); apply(); };~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~      const list = base.filter((b) => !f.cat || b.cat === f.cat);~');
DBMS_OUTPUT.PUT_LINE(q'~      sel('#b-n').textContent = plural(list.length, 'object') + (f.cat ? ' in "' + CATS[f.cat].title + '"' : '');~');
DBMS_OUTPUT.PUT_LINE(q'~      renderTable(host, {~');
DBMS_OUTPUT.PUT_LINE(q'~        rows: list, sort: host._t ? host._t.sort : null, limit: 300, empty: 'Nothing matches.',~');
DBMS_OUTPUT.PUT_LINE(q'~        href: (b) => (b.attempt && b.attempt.op ? '#run/' + b.attempt.op.key : null),~');
DBMS_OUTPUT.PUT_LINE(q'~        cols: [~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'name', label: 'Object', html: (b) => '<code>' + esc(b.name) + '</code>' + (consAll.length > 1 ? ' <span class="pill">' + esc(conName(b.con)) + '</span>' : '') },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'type', label: 'Type', html: (b) => esc(b.type.toLowerCase()) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'cat', label: 'Why', val: (b) => CAT_ORDER.indexOf(b.cat), html: (b) => sevBadge(CATS[b.cat].sev, CATS[b.cat].title, CATS[b.cat].text) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'rows', label: 'Rows (stats)', num: true, html: (b) => fmtN(b.rows) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'dml', label: 'Changed rows', num: true, tip: 'Inserts + updates + deletes since the last gather (DBA_TAB_MODIFICATIONS)', html: (b) => (b.dml ? '<span data-tip="' + esc('ins ' + fmtN(b.ins) + ', upd ' + fmtN(b.upd) + ', del ' + fmtN(b.del) + (b.trunc ? ', truncated' : '')) + '">' + fmtN(b.dml) + '</span>' : (b.trunc ? 'truncated' : '')) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'pct', label: '% changed', num: true, html: (b) => (b.pct != null ? (b.pct >= 1000 ? '>999' : b.pct.toFixed(b.pct < 10 ? 1 : 0)) + '%' : '') },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'analyzed', label: 'Last analyzed', cls: 't', html: (b) => (b.analyzed ? esc(fmtT(b.analyzed)) : '<span class="err">never</span>') },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'dmlTs', label: 'Last change seen', cls: 't', html: (b) => esc(fmtT(b.dmlTs)) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'attempt', label: 'Last gather attempt', cls: 'wrap', val: (b) => (b.attempt ? b.attempt.start : null),~');
DBMS_OUTPUT.PUT_LINE(q'~            html: (b) => (b.attempt ? esc(fmtT(b.attempt.start)) + ' ' + (b.attempt.status === 'FAILED' ? '<span class="err">failed: ' + esc(b.attempt.error || '') + '</span>' : esc(String(b.attempt.status || '').toLowerCase())) : '<span class="note">none in the period</span>') },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'prefs', label: 'Table prefs', cls: 'wrap', val: (b) => b.prefs.length,~');
DBMS_OUTPUT.PUT_LINE(q'~            html: (b) => {~');
DBMS_OUTPUT.PUT_LINE(q'~              const key = b.prefs.filter((p) => /^(STALE_PERCENT|INCREMENTAL|GRANULARITY|PUBLISH)$/.test(p.pref));~');
DBMS_OUTPUT.PUT_LINE(q'~              const rest = b.prefs.length - key.length;~');
DBMS_OUTPUT.PUT_LINE(q'~              return (b.locked ? '<span class="pill">locked ' + esc(b.locked.toLowerCase()) + '</span> ' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~                key.map((p) => '<span class="pill">' + esc(p.pref) + '=' + esc(p.value) + '</span>').join(' ') +~');
DBMS_OUTPUT.PUT_LINE(q'~                (rest ? ' <span class="pill" data-tip="' + esc(b.prefs.map((p) => esc(p.pref) + ' = ' + esc(p.value)).join('<br>')) + '">' + (key.length ? '+' : '') + plural(rest, 'pref') + '</span>' : '');~');
DBMS_OUTPUT.PUT_LINE(q'~            } }~');
DBMS_OUTPUT.PUT_LINE(q'~        ]~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    ['#b-con', '#b-om'].forEach((id) => { if (sel(id)) sel(id).onchange = () => { if (host._t) host._t.limit = 300; apply(); }; });~');
DBMS_OUTPUT.PUT_LINE(q'~    let qt;~');
DBMS_OUTPUT.PUT_LINE(q'~    sel('#b-q').oninput = () => { clearTimeout(qt); qt = setTimeout(apply, 200); };~');
DBMS_OUTPUT.PUT_LINE(q'~    apply();~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // ------------------------------------------------------------ setup~');
DBMS_OUTPUT.PUT_LINE(q'~  function viewConfig() {~');
DBMS_OUTPUT.PUT_LINE(q'~    const v = document.getElementById('view');~');
DBMS_OUTPUT.PUT_LINE(q'~    let h = missingBox();~');
DBMS_OUTPUT.PUT_LINE(q'~    const atc = '<div class="tablewrap"><table><thead><tr><th>Container</th><th>Status</th><th>Window group</th><th class="num">Mean job</th><th class="num">Longest, last 7 days</th><th>Attributes</th></tr></thead><tbody>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      (ATC.length ? ATC.map((a) => '<tr><td>' + esc(conName(a.con)) + '</td><td>' + sevBadge(a.status === 'ENABLED' ? 'good' : 'crit', a.status.toLowerCase()) + '</td><td>' + esc(a.group) + '</td><td class="num">' + esc(fmtDur(a.mean)) +~');
DBMS_OUTPUT.PUT_LINE(q'~        '</td><td class="num">' + esc(fmtDur(a.max7)) + '</td><td>' + esc(a.attrs) + '</td></tr>').join('') : '<tr><td colspan="6" class="note">No rows.</td></tr>') + '</tbody></table></div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    h += panel('Automatic statistics task', 'DBA_AUTOTASK_CLIENT', atc);~');
DBMS_OUTPUT.PUT_LINE(q'~    const wins = WCFG.slice().sort((a, b) => a.con - b.con || (a.next || 9e15) - (b.next || 9e15));~');
DBMS_OUTPUT.PUT_LINE(q'~    renderLater.push(() => renderTable(v.querySelector('#t-win'), {~');
DBMS_OUTPUT.PUT_LINE(q'~      rows: wins, sort: null, limit: 100,~');
DBMS_OUTPUT.PUT_LINE(q'~      cols: [~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'con', label: 'Container', html: (w) => esc(conName(w.con)) },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'name', label: 'Window', html: (w) => esc(w.name) + (w.maint ? ' <span class="pill">maintenance</span>' : '') },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'enabled', label: 'Enabled', html: (w) => (w.enabled === 'TRUE' ? 'yes' : '<span class="err">no</span>') + (w.active === 'TRUE' ? ' <span class="pill">open now</span>' : '') },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'secs', label: 'Duration', num: true, html: (w) => esc(fmtDur(w.secs)) },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'repeat', label: 'Repeat interval', cls: 'wrap', html: (w) => '<code>' + esc(w.repeat) + '</code>' },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'last', label: 'Last opened', cls: 't', html: (w) => esc(fmtT(w.last)) },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'next', label: 'Next', cls: 't', html: (w) => esc(fmtT(w.next)) }~');
DBMS_OUTPUT.PUT_LINE(q'~      ]~');
DBMS_OUTPUT.PUT_LINE(q'~    }));~');
DBMS_OUTPUT.PUT_LINE(q'~    h += panel('Scheduler windows', 'the automatic job runs only while a window of its group is open', '<div id="t-win"></div>');~');
DBMS_OUTPUT.PUT_LINE(q'~    const pr = [...PREFS.entries()];~');
DBMS_OUTPUT.PUT_LINE(q'~    const prefNotes = {~');
DBMS_OUTPUT.PUT_LINE(q'~      AUTOSTATS_TARGET: 'AUTO: all schemas; ORACLE: only Oracle-owned schemas',~');
DBMS_OUTPUT.PUT_LINE(q'~      STALE_PERCENT: 'percent of rows changed before a table counts as stale',~');
DBMS_OUTPUT.PUT_LINE(q'~      CONCURRENT: 'gather several objects at the same time',~');
DBMS_OUTPUT.PUT_LINE(q'~      AUTO_TASK_STATUS: 'high-frequency automatic task (Exadata and Autonomous only in 19c)',~');
DBMS_OUTPUT.PUT_LINE(q'~      AUTO_TASK_MAX_RUN_TIME: 'seconds, high-frequency task',~');
DBMS_OUTPUT.PUT_LINE(q'~      AUTO_TASK_INTERVAL: 'seconds between high-frequency runs'~');
DBMS_OUTPUT.PUT_LINE(q'~    };~');
END;
/
BEGIN
DBMS_OUTPUT.PUT_LINE(q'~    h += '<div class="cols">' + panel('Global preferences', 'DBMS_STATS.GET_PREFS in ' + esc(META.con || ''),~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div class="tablewrap"><table><thead><tr><th>Preference</th><th>Value</th><th></th></tr></thead><tbody>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      pr.map((p) => '<tr><td>' + esc(p[0]) + '</td><td><code>' + esc(p[1]) + '</code></td><td class="note">' + esc(prefNotes[p[0]] || '') + '</td></tr>').join('') + '</tbody></table></div>') +~');
DBMS_OUTPUT.PUT_LINE(q'~      panel('Statistics history', '',~');
DBMS_OUTPUT.PUT_LINE(q'~        '<dl class="kv"><dt>Retention</dt><dd>' + esc(META.retention) + ' days (operations older than this are purged, so this report cannot reach further back)</dd>' +~');
DBMS_OUTPUT.PUT_LINE(q'~        '<dt>Oldest available</dt><dd>' + esc(fmtT(ts(META.availability))) + '</dd><dt>Report period</dt><dd>' + esc(fmtT(T0)) + ' \u2192 ' + esc(fmtT(GEN)) + ' (' + DAYS + ' days)</dd>' +~');
DBMS_OUTPUT.PUT_LINE(q'~        '<dt>Collected as</dt><dd>' + esc(META.user) + ' in ' + esc(META.con) + ' on ' + esc(META.instance) + '</dd>' +~');
DBMS_OUTPUT.PUT_LINE(q'~        '<dt>Embedded rows</dt><dd>' + fmtN(OPS.length) + ' operations, ' + fmtN(TASKS.length) + ' objects (max ' + fmtN(META.maxTasks) + ' per run), ' + fmtN(BL.length) + ' needing statistics</dd></dl>') + '</div><div style="height:16px"></div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    h += panel('Table preferences', 'DBA_TAB_STAT_PREFS (application schemas first)', '<div id="t-tp"></div>');~');
DBMS_OUTPUT.PUT_LINE(q'~    v.innerHTML = h;~');
DBMS_OUTPUT.PUT_LINE(q'~    renderLater.splice(0).forEach((fn) => fn());~');
DBMS_OUTPUT.PUT_LINE(q'~    renderTable(v.querySelector('#t-tp'), {~');
DBMS_OUTPUT.PUT_LINE(q'~      rows: TPREFS, limit: 50, empty: 'No table-level preferences.',~');
DBMS_OUTPUT.PUT_LINE(q'~      cols: [~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'con', label: 'Container', html: (p) => esc(conName(p.con)) },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'owner', label: 'Owner', html: (p) => esc(p.owner) + (p.om ? ' <span class="pill">Oracle</span>' : '') },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'table', label: 'Table' },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'pref', label: 'Preference' },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'value', label: 'Value', cls: 'wrap', html: (p) => '<code>' + esc(p.value) + '</code>' }~');
DBMS_OUTPUT.PUT_LINE(q'~      ]~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  const renderLater = [];~');
DBMS_OUTPUT.PUT_LINE(q'~  // ------------------------------------------------------------ router~');
DBMS_OUTPUT.PUT_LINE(q'~  function route(resize) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const raw = location.hash.replace(/^#/, '') || 'overview';~');
DBMS_OUTPUT.PUT_LINE(q'~    const qi = raw.indexOf('?');~');
DBMS_OUTPUT.PUT_LINE(q'~    const path = (qi < 0 ? raw : raw.slice(0, qi)).split('/');~');
DBMS_OUTPUT.PUT_LINE(q'~    const q = new URLSearchParams(qi < 0 ? '' : raw.slice(qi + 1));~');
DBMS_OUTPUT.PUT_LINE(q'~    const view = path[0];~');
DBMS_OUTPUT.PUT_LINE(q'~    document.querySelectorAll('.top nav a').forEach((a) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const dv = a.getAttribute('data-v');~');
DBMS_OUTPUT.PUT_LINE(q'~      a.classList.toggle('on', dv === view || (dv === 'runs' && view === 'run'));~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    const keepScroll = resize ? window.scrollY : 0;~');
DBMS_OUTPUT.PUT_LINE(q'~    if (view === 'runs') viewRuns(q);~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (view === 'run') viewRun(path[1], path[2]);~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (view === 'backlog') viewBacklog(q);~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (view === 'config') viewConfig();~');
DBMS_OUTPUT.PUT_LINE(q'~    else viewOverview(path[1]);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!(view === 'overview' && path[1])) window.scrollTo(0, keepScroll);~');
DBMS_OUTPUT.PUT_LINE(q'~    document.getElementById('tip').style.display = 'none';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  chrome();~');
DBMS_OUTPUT.PUT_LINE(q'~  wireGlobal();~');
DBMS_OUTPUT.PUT_LINE(q'~  window.addEventListener('hashchange', () => route());~');
DBMS_OUTPUT.PUT_LINE(q'~  route();~');
DBMS_OUTPUT.PUT_LINE(q'~})();~');
DBMS_OUTPUT.PUT_LINE(q'~</script>~');
END;
/
SET DEFINE ON
